const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const storage={get:(k,d)=>{try{return localStorage.getItem(k)??d}catch(e){return d}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}}};
const app=$('#app'),header=$('.header'),stage=$('#stage'),headLeft=$('#headLeft'),headerTitle=$('#headerTitle'),gearBtn=$('#gearBtn'),settingsBar=$('#settingsBar'),toolbelt=$('#toolbelt'),toolScroll=$('#toolScroll'),shade=$('#shade'),nextPeek=$('#nextPeek'),nextPanel=$('#nextPanel'),panelContext=$('#panelContext'),panelPrimary=$('#panelPrimary'),panelSecondary=$('#panelSecondary'),modal=$('#modal'),toast=$('#toast');
const levels=[90,95,100,110,120,130,140,150];
const tokenMap={90:[.90,.90,.92,.90,.95],95:[.95,.95,.96,.95,.97],100:[1,1,1,1,1],110:[1.10,1.08,1.08,1.07,1.04],120:[1.20,1.14,1.15,1.13,1.07],130:[1.30,1.20,1.22,1.19,1.10],140:[1.40,1.27,1.30,1.25,1.13],150:[1.50,1.34,1.38,1.32,1.16]};
