const state={loggedIn:storage.get('aion-v08-auth','in')!=='out',pinned:JSON.parse(storage.get('aion-v08-pinned','[]')||'[]'),workspace:storage.get('aion-v08-workspace','graphite')||'graphite',dim:Number(storage.get('aion-v08-dim','0.02')||0.02),depth:Number(storage.get('aion-v08-depth','1')||1),context:{client:'',device:'',service:'',part:'',supplier:'',order:''},order:{diagnosticsDone:true,approved:false,repairDone:false,sentOtk:false,otkPassed:false,otkProblem:false,total:12500,paid:10000,payment:'partial',issued:false},documents:{intake:true,approval:false,repair:false,final:false}};
